#!/usr/bin/env node
/* Builds src/sim/references.js from REFERENCES.md, so the page can show the full
 * citation, the "Supports" line and the DOI of every reference a scenario cites.
 *
 *   node tools/gen-references.js          rewrites src/sim/references.js
 *   node tools/gen-references.js --check  exits 1 if src/sim/references.js is out of date
 *
 * REFERENCES.md stays the single source; never edit the generated file by hand. */
'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const MD = path.join(ROOT, 'REFERENCES.md');
const JS = path.join(ROOT, 'src', 'sim', 'references.js');

// Markdown emphasis and code marks are dropped; the page shows plain text.
const plain = s => s.replace(/\*\*|\*|`/g, '').replace(/\s+/g, ' ').trim();

/** { number: { cite, supports, doi, url } } from the numbered entries of REFERENCES.md. */
function parse(md) {
  const out = {};
  let cur = null;
  for (const line of md.split('\n')) {
    const m = /^(\d+)\. (.+)$/.exec(line);
    if (m) {
      cur = { cite: plain(m[2]), supports: '' };
      const doi = /doi:\s*(10\.\S+?)\.?(?:\s|$)/.exec(m[2]);
      if (doi) cur.doi = doi[1];
      const url = /(https?:\/\/\S+?)[).,]?(?:\s|$)/.exec(m[2]);
      if (url) cur.url = url[1];
      out[m[1]] = cur;
      continue;
    }
    const s = /^\s+Supports:\s*(.*)$/.exec(line);
    if (s && cur) { cur.supports = plain(s[1]); continue; }
    if (!line.trim() || /^#/.test(line)) cur = null;
  }
  return out;
}

function build(md) {
  const refs = parse(md);
  return '/* Generated by tools/gen-references.js from REFERENCES.md. Do not edit by hand. */\n' +
    '(function (root, factory) {\n' +
    "  if (typeof module === 'object' && module.exports) module.exports = factory();\n" +
    '  else (root.PM = root.PM || {}).references = factory();\n' +
    '})(this, function () {\n' +
    "  'use strict';\n" +
    '  return ' + JSON.stringify(refs, null, 2).replace(/\n/g, '\n  ') + ';\n' +
    '});\n';
}

if (require.main === module) {
  const text = build(fs.readFileSync(MD, 'utf8'));
  if (process.argv.includes('--check')) {
    const same = fs.existsSync(JS) && fs.readFileSync(JS, 'utf8') === text;
    if (!same) { console.error('src/sim/references.js is out of date: run node tools/gen-references.js'); process.exit(1); }
    console.log('src/sim/references.js is up to date');
  } else {
    fs.writeFileSync(JS, text);
    console.log('wrote', path.relative(ROOT, JS), Object.keys(parse(fs.readFileSync(MD, 'utf8'))).length, 'references');
  }
}

module.exports = { parse, build, MD, JS };
